<span class="line">    <span class="token function">Column</span><span class="token punctuation">(</span><span class="token string">&quot;ts&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;DateTime&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
