<span class="line">        fluxaorm<span class="token punctuation">.</span><span class="token function">NewClickhouseTable</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;analytics&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
